import{_ as t,o,c as r,ag as a}from"./chunks/framework.Dk8PTAaz.js";const h=JSON.parse('{"title":"Differences from vue-router","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/differences.md","filePath":"en/guide/differences.md","lastUpdated":1788608281000}'),d={name:"en/guide/differences.md"};function n(s,e,i,c,u,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="differences-from-vue-router" tabindex="-1">Differences from vue-router <a class="header-anchor" href="#differences-from-vue-router" aria-label="Permalink to &quot;Differences from vue-router&quot;">​</a></h1><p>unix-router aligns with vue-router 4 in API style, but because uni-app x uses a <strong>static pages.json page model</strong>, there are fundamental differences between the two. This page explains which capabilities are <strong>implemented equivalently</strong> and which are <strong>not supported</strong>.</p><h2 id="capability-comparison" tabindex="-1">Capability Comparison <a class="header-anchor" href="#capability-comparison" aria-label="Permalink to &quot;Capability Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>vue-router 4</th><th>unix-router (uni-app x)</th></tr></thead><tbody><tr><td><code>createRouter({ history })</code></td><td><code>createRouter({ routes })</code>, no <code>history</code> needed (the native page stack handles it)</td></tr><tr><td>path / named / params / query matching</td><td>✅ Supported</td></tr><tr><td><code>route.params / query / meta / fullPath</code></td><td>✅ Supported (params are passed across pages via query encoding)</td></tr><tr><td><code>currentRoute</code> reactive</td><td>✅ Supported</td></tr><tr><td>push / replace / back</td><td>✅ Supported (+ <code>relaunch</code>)</td></tr><tr><td><code>router.go(n)</code></td><td>⚠️ Limited semantics: degraded to <code>back(delta)</code></td></tr><tr><td>beforeEach / beforeResolve / afterEach</td><td>✅ Supported</td></tr><tr><td>beforeEnter / onBeforeRouteLeave</td><td>✅ Supported</td></tr><tr><td><code>useRouter / useRoute / useLink</code></td><td>✅ Supported</td></tr><tr><td>Error system NavigationFailure</td><td>✅ Supported</td></tr><tr><td><code>isReady / onError</code></td><td>✅ Supported (+ <code>onRouteChange</code>)</td></tr><tr><td><strong>Dynamic routes</strong> <code>addRoute / removeRoute</code></td><td>❌ Not supported (unregistered pages are ignored at compile time)</td></tr><tr><td><strong>Nested routes</strong> <code>children</code></td><td>❌ Not supported (flat page model)</td></tr><tr><td><strong>Named views / RouterView</strong></td><td>❌ Not supported (no in-page rendering placeholder)</td></tr><tr><td><strong>scrollBehavior</strong></td><td>❌ Not supported (scrolling is managed natively by uni-app)</td></tr><tr><td>hash route mode</td><td>❌ Not supported (no URL concept)</td></tr></tbody></table><h2 id="key-differences-explained" tabindex="-1">Key Differences Explained <a class="header-anchor" href="#key-differences-explained" aria-label="Permalink to &quot;Key Differences Explained&quot;">​</a></h2><h3 id="_1-no-url-history" tabindex="-1">1. No URL / history <a class="header-anchor" href="#_1-no-url-history" aria-label="Permalink to &quot;1. No URL / history&quot;">​</a></h3><p>uni-app x has no browser URL; &quot;history&quot; is handled by the native page stack (<code>getCurrentPages</code>). Therefore:</p><ul><li>There is no <code>createWebHistory</code> / <code>createWebHashHistory</code> / <code>createMemoryHistory</code>.</li><li>There are no hash params; scroll behavior is managed natively.</li></ul><h3 id="_2-static-route-table" tabindex="-1">2. Static Route Table <a class="header-anchor" href="#_2-static-route-table" aria-label="Permalink to &quot;2. Static Route Table&quot;">​</a></h3><p>Pages must first be registered in <code>pages.json</code>; at runtime, <code>addRoute</code> cannot compile a page into the bundle → dynamic routes are not supported. Subpackages (<code>subPackages</code>) can act as a resource-level &quot;lazy load&quot;, but they are not vue-router&#39;s nested/dynamic semantics.</p><h3 id="_3-how-params-are-implemented" tabindex="-1">3. How params Are Implemented <a class="header-anchor" href="#_3-how-params-are-implemented" aria-label="Permalink to &quot;3. How params Are Implemented&quot;">​</a></h3><p>The native platform doesn&#39;t support path parameters (the path is the page path). unix-router passes <code>params</code> between page URLs through <strong>query encoding</strong> (reserved <code>__unixr_p_</code> prefix), and the target page can read them from <code>route.params</code>. Therefore:</p><ul><li>params are shaped like <code>Map&lt;string,string&gt;</code> (string values).</li><li>params appear in the URL query in an encoded form (keys are not exposed in plaintext).</li></ul><h3 id="_4-go-n" tabindex="-1">4. <code>go(n)</code> <a class="header-anchor" href="#_4-go-n" aria-label="Permalink to &quot;4. `go(n)`&quot;">​</a></h3><p>vue-router&#39;s <code>go</code> relies on history-based relative navigation, but uni-app x has no such stack API → <code>back(delta)</code> is used instead.</p><h3 id="_5-in-component-guards" tabindex="-1">5. In-Component Guards <a class="header-anchor" href="#_5-in-component-guards" aria-label="Permalink to &quot;5. In-Component Guards&quot;">​</a></h3><p>uni-app x creates a new page instance for every navigation (no keep-alive), so <code>onBeforeRouteUpdate</code> rarely triggers, <code>onBeforeRouteEnter</code> has limited effect, and <code>onBeforeRouteLeave</code> is the most commonly used.</p><h2 id="migration-mindset" tabindex="-1">Migration Mindset <a class="header-anchor" href="#migration-mindset" aria-label="Permalink to &quot;Migration Mindset&quot;">​</a></h2><p>If you&#39;re coming from vue-router, most of your code migrates directly: <code>createRouter</code>, guards, <code>useRouter/useRoute/useLink</code>, and <code>push/replace/back</code> are all used the same way; you only need to move the <code>components</code> config to <code>pages.json</code> registration and drop dynamic routes / nesting / named views.</p>',19)])])}const m=t(d,[["render",n]]);export{h as __pageData,m as default};
